css:
body, .print-format{
  font-size: 12px !important;
  font-family: Arial, sans-serif;
  padding: 0px ;
}

/* Header ke liye padding */
.print-format-header {
  padding: 10px 25px; /* top-bottom 10px, left-right 25px */
  margin: 0 auto;
}

/* Pricetable adjustments */
.pricetable {
  width: 100%;
  border-collapse: collapse;
  font-size: 11px;
}

.pricetable th, .pricetable td {
  border: 1px solid #ccc;
  padding: 6px;
  word-wrap: break-word;
  white-space: normal;
  font-size: 10px; /* aur compact */
}

.pricetable thead th {
  background: #f0f0f0;
  font-weight: bold;
}

.pricetable .text-right {
  text-align: right;
}
.print-format h1, 
.print-format h1 * {
  font-size: 18px !important;
  color: #A11929;
  margin: 0;
  letter-spacing: 2px;
}
